from pathlib import Path
import json,csv,html
R=Path(__file__).resolve().parent
records=json.loads((R/'scene.json').read_text());parts=[r for r in records if not r['component']]
with (R/'PARTS.csv').open('w',newline='',encoding='utf-8-sig') as f:
    w=csv.writer(f);w.writerow(['Assembly','Printed part','Quantity','STL','Notes'])
    for r in parts:w.writerow([r['role'],r['name'],1,r['file'],r['notes']])
def pic(name,caption,wide=False):
    return f'<figure class="{"wide" if wide else ""}"><a href="previews/{name}.png" target="_blank"><img src="previews/{name}.png" alt="{html.escape(caption)}" loading="lazy"></a><figcaption>{caption}</figcaption></figure>'
body='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dual-Reality Maze · Revision 11</title><style>
:root{--bg:#101316;--panel:#1b2026;--gold:#e2b981;--muted:#aeb8c4;--line:#343d47}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:80px}body{margin:0;background:var(--bg);color:#f0eee8;font:16px/1.65 system-ui,sans-serif}main{max-width:1320px;margin:auto;padding:48px 26px 80px}h1,h2{font-family:Georgia,serif;font-weight:400;line-height:1.15;color:var(--gold)}h1{font-size:clamp(40px,6vw,76px);margin:10px 0 20px}h2{font-size:38px;margin:70px 0 20px}h3{font-size:22px;margin:0 0 10px}p{max-width:900px}.eyebrow{letter-spacing:.16em;text-transform:uppercase;color:var(--gold);font-size:12px}.lead{font-size:21px;color:#cad1da;max-width:920px}.muted,figcaption{color:var(--muted)}nav{position:sticky;top:0;z-index:5;background:#101316f2;border-block:1px solid var(--line);padding:12px 26px;backdrop-filter:blur(12px);display:flex;gap:24px;overflow:auto}nav a,a{color:var(--gold);text-decoration:none}nav a{white-space:nowrap}a:hover{text-decoration:underline}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.three{grid-template-columns:repeat(3,minmax(0,1fr))}.wide{grid-column:1/-1}figure{margin:0;background:var(--panel);border:1px solid var(--line);border-radius:15px;overflow:hidden}figure img{width:100%;height:auto;display:block}figcaption{padding:15px 18px;font-size:14px}.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:24px;margin:20px 0}.controls{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}button{background:#252d36;color:#e6e9ed;border:1px solid #48535f;border-radius:8px;padding:10px 16px;font:inherit;cursor:pointer}button.active,button:hover{background:var(--gold);color:#15191e;border-color:var(--gold)}.chips{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0 18px}.chip{font-size:13px;background:#252b33;border:1px solid #414a54;border-radius:24px;padding:6px 12px}.status{border-left:3px solid var(--gold);padding:10px 18px;background:#1e242b;color:#c6cfd8;max-width:1100px}.caption{min-height:3.3em}.section-no{color:#798694;font:14px system-ui;letter-spacing:.1em}footer{margin-top:70px;padding-top:20px;border-top:1px solid var(--line);color:var(--muted)}.downloads{display:flex;flex-wrap:wrap;gap:12px 24px}.zoomnote{font-size:13px;color:var(--muted)}@media(max-width:760px){.grid,.three{grid-template-columns:1fr}main{padding:30px 16px}h2{font-size:30px}.card{padding:16px}nav{gap:17px;padding:10px 16px;font-size:14px}}
</style></head><body><nav><a href="#cases">The three enclosures</a><a href="#adjust">Adjust &amp; lock</a><a href="#controls">Control fittings</a><a href="#gate">Build the gate</a><a href="#engraving">Engraving close-ups</a></nav><main><div class="eyebrow">Soham Basanwar · CAD revision 10 · 29 October 2026</div><h1>Made to fit.<br>Built to be opened.</h1><p class="lead">The fantasy shells, removable covers and gate remain. Inside, indexed sliding jaws and keyed height inserts make the board mounts adjustable without screws.</p><p class="status">These pictures render the actual CAD solids. Printed fit, latch strength, optical transmission and powered operation still require physical tests. Electronics are simplified reference shapes; coloured highlights identify parts, not a multicolour printing requirement.</p><p class="zoomnote">Click any picture to inspect it at full resolution.</p>'''
body+='<section id="cases"><h2><span class="section-no">01 / </span>The three enclosures</h2><p>Release the side latches, lift the front and disengage the rear tabs. The battery doors and cable shutters operate separately.</p>'
for role in ['explorer','architect','main']:
    body+=f'<article class="card"><h3>{role.title()}</h3><div class="controls" data-role="{role}">'
    for mode,label in [('closed','Closed'),('open','Lid removed'),('base','Base & boards'),('lid','Under the lid'),('battery-closed','Battery closed'),('battery-open','Battery open'),('cables-closed','Cables closed'),('cables-open','Cables open')]:
        body+=f'<button class="{"active" if mode=="closed" else ""}" onclick="caseView(this,\'{role}\',\'{mode}\')">{label}</button>'
    body+=f'</div><figure><a id="{role}-link" href="previews/{role}-closed.png" target="_blank"><img id="{role}-case" src="previews/{role}-closed.png" alt="{role.title()} enclosure" loading="lazy"></a><figcaption id="{role}-caption">Closed assembly. The outer shape and contoured battery-door surface are retained.</figcaption></figure></article>'
body+='</section><section id="adjust"><h2><span class="section-no">02 / </span>Adjust. Insert the key. Check the fit.</h2><p>The fixed corner locates the board. Two jaws set its length and breadth. Pull a locking key sideways, move its jaw, then align and fully reinsert the key. The key carries the sliding load; avoid squeezing the electronics.</p><p>The recessed <strong>+ ↔ −</strong> symbols indicate a larger or smaller opening. The nominal setting is the largest front-to-back setting in the handheld bases: the battery bay and adjacent board limit further growth. Main and the control carriers have room on both sides of nominal.</p><p class="status">Indexed settings are 3 mm apart. Small nonconductive fit pads may be needed between settings. They must touch safe edges, not solder joints or electronic parts. Open the jaws for installation; only use a position with a complete locking-key passage.</p>'
for role in ['explorer','architect','main']:
    body+=f'<h3 style="margin-top:38px">{role.title()} mounting system</h3><div class="grid">'
    for item in sorted(json.loads((R/(role+'-adjustments.json')).read_text()), key=lambda x:['Breadboard','UNO','Joystick','LCD'].index(x['prefix'])):
        pre=item['prefix'];uid=role+'-'+pre.lower();w,d,t=item['nominal_mm'];rx=item['axes'][0]['range_mm'];ry=item['axes'][1]['range_mm']
        body+=f'<article class="card"><h3>{pre}</h3><div class="chips"><span class="chip">Nominal {w:g} × {d:g} × {t:g} mm</span><span class="chip">Length {w+min(rx):g}–{w+max(rx):g}</span><span class="chip">Breadth {d+min(ry):g}–{d+max(ry):g}</span></div><div class="controls">'
        for mode,label in [('nominal','Default'),('minus','− Smaller'),('plus','+ Largest'),('unlocked','Keys released'),('height','Height insert')]:
            body+=f'<button class="{"active" if mode=="nominal" else ""}" onclick="mountView(this,\'{uid}\',\'{mode}\')">{label}</button>'
        body+=f'</div><figure><a id="{uid}-link" href="previews/{uid}-nominal.png" target="_blank"><img id="{uid}-image" src="previews/{uid}-nominal.png" alt="{pre} adjustable mounting frame" loading="lazy"></a><figcaption id="{uid}-caption">Nominal frame, height insert and two locked jaws. Electronics omitted to expose the mechanism.</figcaption></figure>'
        body+=pic(uid+'-arrows','Close-up: actual recessed direction marks, captured slider and removable cross key.')+'</article>'
    body+='</div>'
body+='''<div class="card"><h3>Height uses one matched insert</h3><p><strong>0.6 mm / 1.2 mm default / 1.8 mm</strong> inserts change support height by −0.6 / 0 / +0.6 mm. Use one keyed frame, never a stack. A thicker insert supports a thinner board under the fixed upper lips; a thinner insert accommodates a thicker board. Check that the display, joystick and connectors still align.</p><p>The smaller/larger PCB allowances concern board edges. A different shaft offset, LCD glass position or header layout can still require a different carrier.</p></div></section>'''
body+='<section id="controls"><h2><span class="section-no">03 / </span>The controls keep their alignment</h2><div class="grid">'
for name,caption in [
('ldr-open','Explorer: quarter-turn dome removed. Fit the photoresistor above the isolated floor, pass its two leads through the individual holes, then replace and turn the dome. Its position is fixed.'),
('pot-mount','Architect: potentiometer body cup and removable keeper. Shaft centre and terminal clearance remain fixed; this is a replaceable fitting, not a sliding rail.'),
('button-linkage','Architect: the cap drives the breadboard switch through a guided stem and replaceable lower contact shoe. Nominal / ±0.6 mm reach alternatives tune the real switch gap. Remove the guide and pinch the shoe’s snap tabs through the stem windows to release it.'),
('buzzer-mount','Main: buzzer cup and removable keeper. The sound opening stays aligned; the actual sounder must fit the selected ring.')]:body+=pic(name,caption)
body+='</div><p>RGB retainers keep each LED aligned with its emblem. The battery bay and grip-facing cover retain their dedicated shape. The photoresistor roof is an optical test; a clear-film alternative is supplied if the chosen opaque filament blocks light.</p></section>'
body+='<h3>Choose one button contact tip</h3><p>The snap connection stays the same. Only the lower contact length changes. Compare these with the real installed switch height; the longer option must not preload the switch.</p><div class="grid three">'
for mode,cap in [('minus','−0.6 mm reach · shorter contact'),('nominal','Default · nominal contact'),('plus','+0.6 mm reach · longer contact')]:body+=pic('button-reach-'+mode,cap)
body+='</div>'
body+='<section id="gate"><h2><span class="section-no">04 / </span>Build the gate, from the inside out</h2><p>The servo turns its supplied nylon horn. A retained pin travels along the horizontal slot in the gate panel, converting rotation into vertical lift. The frame guides the gate; the removable guard closes the rail ends.</p><div class="grid">'
for key,caption in [
('01-servo','1 · Seat the keyed fitting insert, place the SG90 body in the cassette, and latch the removable bridge. Width inserts allow ±0.6 mm around the nominal body while keeping it centred.'),
('02-horn','2 · Fit the servo’s original nylon horn at the correct starting angle. The CAD does not assume a printable replacement for its spline.'),
('03-frame-panel','3 · Install the cassette and frame into their lid receivers. Slide the gate panel down from the open top of the guide rails.'),
('04-pin','4 · Align the horn hole with the panel slot. Pass the headed drive pin through both, then fit its small rear keeper. Check free motion before powering.'),
('05-guard','5 · Clip on the guard after the linkage is connected. The frame bridge retains the horn axially; the guard keeps the gate from escaping upward.'),
('06-closed','6 · Closed assembly. Confirm that the selected servo’s horn, ears and output-shaft position match before printing the whole mechanism.')]:body+=pic('gate-'+key,caption)
body+='</div><div class="card"><h3>Opening and closing</h3><div class="controls"><button class="active" onclick="gateView(this,false)">Closed · −60°</button><button onclick="gateView(this,true)">Open · +60°</button></div><figure><a id="gate-link" href="previews/gate-06-closed.png" target="_blank"><img id="gate-image" src="previews/gate-06-closed.png" alt="Gate motion" loading="lazy"></a><figcaption>Nominal 7 mm crank radius; about 12.12 mm lift over the illustrated range. Establish safe powered endpoints gradually after assembly.</figcaption></figure></div></section>'
body+='<h3>Choose one servo fitting insert</h3><p>These liners exchange wall thickness to change the body opening while keeping the servo centred. Output shaft and ear positions still need checking.</p><div class="grid three">'
for mode,cap in [('minus','−0.6 mm body width · thicker walls'),('nominal','Default · nominal 23 mm body'),('plus','+0.6 mm body width · thinner walls')]:body+=pic('servo-width-'+mode,cap)
body+='</div>'
body+='<section id="engraving"><h2><span class="section-no">05 / </span>Soham Basanwar · SB</h2><p>Close views of the recessed lettering on the actual printed geometry.</p><div class="grid">'
for name,cap in [('engraving-base','Full name · underside of the shell'),('engraving-lid','Full name · inside the lid'),('engraving-door','Full name · inside the contoured battery door'),('engraving-insert','Full name · height insert'),('engraving-jaw','SB · slider jaw'),('engraving-shutter','SB · shutter finger tab')]:body+=pic(name,cap)
body+='</div><div class="grid three" style="margin-top:20px">'
for name,cap in [('printed-parts-full-name','Printed pieces with the full name'),('printed-parts-sb','Printed pieces with SB'),('printed-parts-unmarked','Small or fit-sensitive printed pieces left unmarked')]:body+=pic(name,cap)
body+='</div></section><footer><p>Print the small rail, jaw and locking-key coupons first. Check release, retention and fit before full shells. Printed parts are separate STL files; several may share a build plate. The alternative inserts are substitutions, not extra installed layers.</p><div class="downloads"><a href="PARTS.csv">Print parts file</a><a href="PRINT_AND_ASSEMBLY.md">Assembly and print guidance</a><a href="REVIEW_VALIDATION.json">Digital checks</a>'
for role in ['explorer','architect','main']:body+=f'<a href="cad/{role}-revision11.FCStd">{role.title()} · FreeCAD</a>'
body+='</div></footer></main>'
body+='''<script>
function activate(b){for(const x of b.parentElement.querySelectorAll('button'))x.classList.remove('active');b.classList.add('active')}
function swap(id,src){document.getElementById(id).src=src}
function caseView(b,r,m){activate(b);let src=`previews/${r}-${m}.png`;swap(r+'-case',src);document.getElementById(r+'-link').href=src;document.getElementById(r+'-caption').textContent={closed:'Closed assembly. Outer shape and contoured battery-door surface retained.',open:'Lid assembly moved aside for inspection; this is an exploded layout, not a hinge.',base:'Base hardware and adjustable board mounts. Orange/green blocks reserve space for unselected power/ESP32 hardware.',lid:'The underside of the lid exposes control fittings and their components.','battery-closed':'Battery cover seated in the original curved grip surface.','battery-open':'Cover withdrawn for access. Release the catch and disengage the two locating tabs.','cables-closed':'Cable shutters closed. Main has two side I2C entries and a separate rear USB fallback opening.','cables-open':'Shutters parked open. Remove cables before closing; use the separate internal strain relief.'}[m]}
function mountView(b,id,m){activate(b);let src=`previews/${id}-${m}.png`;swap(id+'-image',src);document.getElementById(id+'-link').href=src;document.getElementById(id+'-caption').textContent={nominal:'Default dimensions, nominal height insert and two fully engaged locking keys.',minus:'Both jaws at the smaller indexed setting. Electronics omitted to expose the mechanism.',plus:'Largest permitted indexed setting for this particular mount; use the limits above.',unlocked:'Keys withdrawn sideways. Set the jaws, align the passages and reinsert each key completely.',height:'Nominal height insert lifted out for illustration. Replace it with one chosen thickness; do not stack.'}[m]}
function gateView(b,o){activate(b);let src='previews/gate-'+(o?'07-open':'06-closed')+'.png';swap('gate-image',src);document.getElementById('gate-link').href=src}
</script></body></html>'''
(R/'index.html').write_text(body,encoding='utf-8')
print('R11 visual guide created; images must pass checks before delivery')
